import type { Scenario, Scene, SeasonKey } from '../types';
import { largeAdventure, largeEnd, largeScene, largeTags } from './largeContentTools';

const s = (id: string, title: string, text: string, choices: Scene['choices'], tone: Scene['tone'] = 'safe') => largeScene(id, title, text, choices, tone);
const e = (id: string, title: string, text: string) => largeEnd(id, title, text);
const itemPay = (id: string, provenance: string, flag: string) => ({ gainItems: [id], gainItemProvenance: { [id]: provenance }, historyFlags: [flag] });
type Risk = 'LOW' | 'MODERATE' | 'HIGH';
const monthsFor = (season: SeasonKey) => season === 'SPRING' ? [3, 4, 5] : season === 'SUMMER' ? [6, 7, 8] : season === 'AUTUMN' ? [9, 10, 11] : season === 'WINTER' ? [12, 1, 2] : Array.from({ length: 12 }, (_, i) => i + 1);
const a = (id: string, title: string, subtitle: string, hook: string, setting: string, risk: Risk, start: string, scenes: Record<string, Scene>, options: { season?: SeasonKey; combat?: 'NONE' | 'POSSIBLE'; activity?: string; structures?: string[] } = {}): Scenario => {
  const season = options.season ?? 'ALL_YEAR';
  const metadata = largeTags({
    hook, role: 'worker', activity: options.activity ?? 'labor/repair', tone: risk === 'LOW' ? 'adventurous' : 'tense/dangerous', risk,
    setting, combat: options.combat ?? 'NONE', structures: options.structures ?? ['rural work develops a second problem', 'animal/property priority changes the plan'],
    entry: ['hired/posted work', 'accidental encounter'], rewards: ['Gear', 'coins', 'Knowledge'],
    outcomes: ['success/partial success', 'walk-away/refusal', 'costly success/no-perfect-outcome possible'],
  });
  metadata.availability = { season, months: monthsFor(season) };
  return largeAdventure(id, title, subtitle, metadata, start, scenes);
};

